require(['jquery'], $ => {
  'use strict';

  // The last notification of each test button, replaced by the next one so that an outdated outcome does not stay.
  const notifications = new WeakMap();

  /**
   * Show a notification about the test of a server, in place of the last one of its button.
   *
   * @param {HTMLButtonElement} button the test button of the server
   * @param {string} message the message, plain text
   * @param {string} type the notification type: inprogress, done or error
   * @param {object} [options] the options of the notification, e.g. its timeout
   */
  function notify(button, message, type, options) {
    const text = `${button.dataset.serverLabel} ${message}`;
    // XWiki 17.10.9, and 18.4.0 and later, show the text of a notification as plain text and define textFormat;
    // earlier versions show it as HTML.
    const content = typeof XWiki.widgets.Notification.textFormat === 'function' ? text : text.escapeHTML();
    const notification = new XWiki.widgets.Notification(content, type, {...options, inactive: true});
    const last = notifications.get(button);
    notifications.set(button, notification);
    if (last) {
      last.replace(notification);
    } else {
      notification.show();
    }
  }

  /**
   * Test the saved configuration of a server and show the outcome in a notification: a success for a few seconds, a
   * failure until it is clicked, as it says what to correct.
   *
   * @param {HTMLButtonElement} button the test button, carrying the URL of the test and the messages it needs
   */
  async function testServer(button) {
    // Not disabled while the test runs, as disabling the button would make it lose the keyboard focus.
    if (button.getAttribute('aria-disabled') === 'true') {
      return;
    }
    button.setAttribute('aria-disabled', 'true');
    // Bootstrap styles the class, not the attribute.
    button.classList.add('disabled');
    try {
      notify(button, button.dataset.testingMessage, 'inprogress');
      // XWiki's xwiki.js adds the XWiki-Form-Token header to every same-origin fetch; setting it here too would send two
      // tokens, which the server receives as one invalid, comma-joined value.
      const response = await fetch(button.dataset.testUrl, {
        method: 'POST',
        headers: {'Accept': 'application/json'}
      });
      // Every answer of the test resource carries a message, refusals included.
      const answer = await response.json();
      if (answer.message && answer.success === true) {
        notify(button, answer.message, 'done', {timeout: 5});
      } else {
        notify(button, answer.message || button.dataset.errorMessage, 'error', {timeout: false});
      }
    } catch (error) {
      console.error('Failed to test the AI server configuration.', error);
      notify(button, button.dataset.errorMessage, 'error', {timeout: false});
    } finally {
      button.removeAttribute('aria-disabled');
      button.classList.remove('disabled');
    }
  }

  $(document).on('click', '.llm-server-test', event => testServer(event.currentTarget));
});
